import time
from Pytrich.Heuristics.heuristic import Heuristic
from Pytrich.Search.htn_node import HTNNode
from Pytrich.model import Model

# This was generated by Claude
# Domain dependant heuristic for depot domain to be used as an example when prompting LLMs to generate heuristics
class DepotGemini20FlashHeuristic21(Heuristic):
    def __init__(self, depot_gemini20flash_heuristic_21=0, move_penalty=0.1, lift_penalty=0.2, name="depot_gemini20flash_heuristic21"):
        super().__init__(name=name)
        self.move_penalty = move_penalty
        self.lift_penalty = lift_penalty
        self.method_scores = {}
        self.preprocessing_time = 0

    def initialize(self, model, initial_node):
        """
        Initialize the heuristic with the model and precompute method characteristics.
        """
        start_time = time.time()
        self.model = model
        self._precompute_method_info()
        self.preprocessing_time = time.time() - start_time

        # Calculate initial heuristic value
        h_value = self._calculate_node_heuristic(initial_node)

        return super().initialize(model, h_value)

    def _precompute_method_info(self):
        """
        Precompute information about methods for faster scoring.
        """
        if not self.model:
            return

        # Get methods from the model
        methods = []
        if hasattr(self.model, 'methods'):
            methods = self.model.methods
        elif hasattr(self.model, 'decompositions'):
            methods = self.model.decompositions
        elif hasattr(self.model, 'tasks'):
            # Get methods from abstract tasks
            for task in self.model.tasks:
                if hasattr(task, 'decompositions'):
                    methods.extend(task.decompositions)

        if not methods:
            return

        for method in methods:
            method_name = method.name if hasattr(method, 'name') else str(method)

            # Count different types of operations in subtasks
            move_count = 0
            lift_count = 0
            subtask_count = 0

            # Get subtasks from method
            subtasks = []
            if hasattr(method, 'subtasks'):
                subtasks = method.subtasks
            elif hasattr(method, 'task_network'):
                subtasks = method.task_network
            elif hasattr(method, 'decomposition'):
                subtasks = method.decomposition

            if subtasks:
                subtask_count = len(subtasks)
                for subtask in subtasks:
                    subtask_name = ""
                    if hasattr(subtask, 'name'):
                        subtask_name = subtask.name
                    elif hasattr(subtask, 'task'):
                        subtask_name = str(subtask.task)
                    else:
                        subtask_name = str(subtask)

                    subtask_lower = subtask_name.lower()

                    # Count different operation types
                    if 'move' in subtask_lower:
                        move_count += 1
                    if 'lift' in subtask_lower or 'load' in subtask_lower or 'unload' in subtask_lower or 'store' in subtask_lower:
                        lift_count += 1

            self.method_scores[method_name] = {
                'move_count': move_count,
                'lift_count': lift_count,
                'subtask_count': subtask_count,
                'is_move_method': self._is_move_method(method_name),
                'is_lift_method': self._is_lift_method(method_name),
                'is_base_case': self._is_base_case_method(method_name),
                'is_goal_achieving': self._is_goal_achieving_method(method_name),
                'complexity_score': move_count + lift_count
            }

    def _is_move_method(self, method_name):
        """Check if method is for moving. This is a relaxed check"""
        return 'move' in method_name.lower()

    def _is_lift_method(self, method_name):
        """Check if method is for lifting/loading/unloading.  This is a relaxed check"""
        return 'lift' in method_name.lower() or 'load' in method_name.lower() or 'unload' in method_name.lower() or 'store' in method_name.lower()


    def _is_base_case_method(self, method_name):
        """Check if method is a base case (no further decomposition needed)."""
        return 'base' in method_name.lower() or 'done' in method_name.lower()

    def _is_goal_achieving_method(self, method_name):
        """Check if method directly contributes to achieving a goal."""
        return 'achieve' in method_name.lower() or 'finish' in method_name.lower()

    def _calculate_node_heuristic(self, node):
        """
        Calculate heuristic value for a node based on its decomposition method.
        Return small values to ensure admissibility while providing guidance.
        """
        if not hasattr(node, 'method') or not node.method:
            return 0

        return self._score_method(node.method, node)

    def _score_method(self, method, node):
        """
        Score a method based on various factors.
        Lower scores indicate more promising methods (cost-based heuristic).
        All values kept small to maintain admissibility.
        """
        score = 0  # Start with 0 cost

        method_name = method.name if hasattr(method, 'name') else str(method)
        method_lower = method_name.lower()

        # Use precomputed info if available
        if method_name in self.method_scores:
            info = self.method_scores[method_name]

            # Penalize based on operation complexity
            score += info['move_count'] * self.move_penalty
            score += info['lift_count'] * self.lift_penalty

            # Give bonuses (negative cost) for productive methods
            if info['is_goal_achieving']:
                score -= 0.05  # Small bonus for methods that achieve goals

            if info['is_base_case']:
                score -= 0.02  # Smaller bonus for base cases

        # Additional heuristics based on names (less reliable)
        if 'move' in method_lower:
            score += self.move_penalty / 2  # small additional penalty
        if 'lift' in method_lower or 'load' in method_lower or 'unload' in method_lower:
            score += self.lift_penalty / 2  # small additional penalty

        return max(score, 0)

    def __call__(self, parent_node, node):
        """
        Calculate heuristic value for the given node.
        Keep values small for admissibility while providing search guidance.
        """
        h_value = self._calculate_node_heuristic(node)
        # Ensure values stay reasonable for admissibility
        h_value = min(h_value, 1.0)
        super().update_info(h_value)
        return h_value

    def __repr__(self):
        return f"DepotGemini20FlashHeuristic21(move_penalty={self.move_penalty}, lift_penalty={self.lift_penalty})"

    def __str__(self):
        return f"DepotGemini20FlashHeuristic21(move_penalty={self.move_penalty}, lift_penalty={self.lift_penalty})"

    def __output__(self):
        return (
            f"Depot Gemini 2.0 Flash Heuristic 21 info:\n"
            f"\tName: {self.name}\n"
            f"\tMethods analyzed: {len(self.method_scores)}\n"
            f"\tMove penalty: {self.move_penalty}\n"
            f"\tLift penalty: {self.lift_penalty}\n"
            f"\tPreprocessing time: {self.preprocessing_time:.2f} s\n"
        )
